import React, { useState } from 'react';
import { useLocation, Link, useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { WalletModal } from '../pages/WalletPage'; // Import the wallet modal component

const Header = ({ balance, setBalance, notifications }) => {
  const location = useLocation();
  const navigate = useNavigate();
  const { user } = useAuth();
  const [showWalletModal, setShowWalletModal] = useState(false);

  // Auto-open wallet modal when on /wallet route
  React.useEffect(() => {
    if (location.pathname === '/wallet') {
      setShowWalletModal(true);
      // In a real scenario, we'd navigate to coinflip but keep modal open
      // But for now we'll just open the modal when wallet button is clicked
    }
  }, [location.pathname]);

  const getPageTitle = () => {
    switch(location.pathname) {
      case '/coinflip':
        return 'Coinflip';
      case '/blackjack':
        return 'Blackjack';
      case '/wallet':
        return 'Wallet';
      case '/leaderboard':
        return 'Leaderboard';
      case '/stats':
        return 'Statistics';
      case '/provably-fair':
        return 'Provably Fair';
      case '/profile':
        return 'Profile';
      case '/admin':
        return 'Admin Panel';
      default:
        return 'Dashboard';
    }
  };

  const handleWalletClick = () => {
    setShowWalletModal(true);
  };

  const handleProfileClick = (e) => {
    e.preventDefault(); // Prevent default link behavior
    navigate('/stats'); // Navigate to stats page
  };

  return (
    <header className={`header ${user ? 'with-sidebar' : ''}`}>
      <div className="header-left">
        <h2>{getPageTitle()}</h2>
      </div>

      <div className="header-right">
        <div className="balance-display">
          {balance?.toLocaleString()} <span className="ampcoin-text">AMP</span>
        </div>

        <button 
          className="wallet-btn btn btn-secondary"
          onClick={handleWalletClick}
        >
          Wallet
        </button>

        <Link to="/stats" className="user-profile-link" onClick={handleProfileClick}>
          <img 
            src={user?.avatar || '/default-avatar.png'} 
            alt="Avatar" 
            className="user-avatar"
            onError={(e) => {
              e.target.src = '/default-avatar.png';
            }}
          />
          <span className="username">{user?.displayName}</span>
        </Link>

        <div className="notifications">
          <span className="notification-icon">🔔</span>
          {notifications && notifications.length > 0 && (
            <span className="notification-badge">{notifications.length}</span>
          )}
        </div>
      </div>

      {/* Wallet Modal */}
      {showWalletModal && (
        <div className="modal-overlay" onClick={() => setShowWalletModal(false)}>
          <div className="wallet-modal" onClick={(e) => e.stopPropagation()}>
            <div className="modal-header">
              <h2>Wallet</h2>
              <button className="close-modal" onClick={() => setShowWalletModal(false)}>×</button>
            </div>
            <WalletModal onClose={() => setShowWalletModal(false)} />
          </div>
        </div>
      )}
    </header>
  );
};

export default Header;
